<?php
namespace App\Services\Payments\Gateways;
class PesapalGateway extends AbstractHttpGateway{
 private function cfg(string $k){return $this->setting($k, config("payment_gateways.pesapal.$k"));}
 private function token():string{$r=$this->http()->post(rtrim($this->cfg('base_url'),'/').'/Auth/RequestToken',['consumer_key'=>$this->required($this->cfg('consumer_key'),'PESAPAL_CONSUMER_KEY'),'consumer_secret'=>$this->required($this->cfg('consumer_secret'),'PESAPAL_CONSUMER_SECRET')])->throw()->json();return $this->required($r['token']??null,'Pesapal token');}
 public function initiate(array $p):array{$payload=['id'=>$p['reference'],'currency'=>$p['currency']??'UGX','amount'=>$p['amount'],'description'=>$p['description']??'Hotel reservation payment','callback_url'=>$p['callback_url'],'notification_id'=>$this->required($this->cfg('ipn_id'),'PESAPAL_IPN_ID'),'billing_address'=>['email_address'=>$p['email']??'','phone_number'=>$p['phone']??'','first_name'=>$p['first_name']??'Guest','last_name'=>$p['last_name']??'']];$r=$this->http(['Authorization'=>'Bearer '.$this->token()])->post(rtrim($this->cfg('base_url'),'/').'/Transactions/SubmitOrderRequest',$payload)->throw()->json();return ['mode'=>'redirect','gateway'=>'pesapal','redirect_url'=>$r['redirect_url']??null,'gateway_reference'=>$r['order_tracking_id']??null,'response'=>$r];}
 public function verify(string $reference):array{$r=$this->http(['Authorization'=>'Bearer '.$this->token()])->get(rtrim($this->cfg('base_url'),'/').'/Transactions/GetTransactionStatus',['orderTrackingId'=>$reference])->throw()->json();$code=(int)($r['status_code']??0);return ['successful'=>$code===1,'status'=>$r['payment_status_description']??'unknown','amount'=>(float)($r['amount']??0),'currency'=>$r['currency']??null,'gateway_reference'=>$reference,'raw'=>$r];}
}
